edits.after:
@media(max-width:480px){
  body #product-screen.nd-v1-product #product-tax-block.product-business-aggregate
    .grid:has(> [data-pricing-decision]){
    grid-template-columns:minmax(0,1fr);
  }
  body #product-screen.nd-v1-product #product-tax-block.product-business-aggregate
    :is(.aggregate-action-confirm,.aggregate-action-recalc){
    font-size:clamp(20px,5.8vw,24px);
  }
}
/* Warning and loss classes retain their controller-defined semantic colors. */
